-- AI 영상 분석 벤치마크. 관리 API 없이 운영자가 SQL로 직접 넣으므로 생성·수정 시각에 기본값을 둔다.
-- 영상은 분석 스토리지(GCS)의 객체 키로 두고, 조회 시 서명 URL을 발급한다.
CREATE TABLE "benchmarks" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "title" VARCHAR(100) NOT NULL,
    "video_object_key" VARCHAR(512) NOT NULL,
    "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uk_benchmarks_video_object_key" UNIQUE ("video_object_key")
);

-- 평가지표는 서버가 해석하지 않고 JSON 객체 그대로 저장한다.
CREATE TABLE "benchmark_results" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "benchmark_id" BIGINT NOT NULL,
    "metrics" JSONB NOT NULL,
    "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "fk_benchmark_results_benchmark" FOREIGN KEY ("benchmark_id") REFERENCES "benchmarks" ("id"),
    CONSTRAINT "chk_benchmark_results_metrics" CHECK (jsonb_typeof("metrics") = 'object')
);

CREATE INDEX "idx_benchmark_results_benchmark_id" ON "benchmark_results" ("benchmark_id", "id" DESC);
